from lib import *
S = SS('w101')
steps = [
    step("SOCKS5 握手的每个字节(RFC 1928)。我自己实现了一个 SOCKS5 服务器,用套接字手工连它。客户端问候 05 01 00:05 = 版本,01 = 1 种认证方法,00 = “无需认证”;服务器选择 05 00:选定无需认证(ff 表示没有可接受的方法)。客户端请求 05 01 00 01 7f 00 00 01 24 ba:05 版本 | 01 = CONNECT | 00 保留 | 01 = 地址类型 IPv4 | 7f 00 00 01 = 127.0.0.1 | 24 ba = 端口 9402。服务器回复 05 00 00 01 7f 00 00 01 e7 12:05 | 00 = 成功 | 00 保留 | 01 = IPv4 | 本地地址 127.0.0.1 与端口 59154(服务器一侧出站连接的 BND.ADDR / BND.PORT)。之后这条 TCP 连接就成了一根透明的管子,收到目标发来的 “hello from target”。整个握手 2 个往返(问候 / 选择 1 个,请求 / 回复 1 个),上行 13 字节,下行 12 字节。", t=tl(S(1)), mark=lidx(S(1), '客户端问候', '客户端请求'), done=lidx(S(1), '服务器选择', '服务器回复', '之后这条 TCP 连接', '整个握手'), b=bars([['上行', 13, '13 字节'], ['下行', 12, '12 字节']], 13, mark=[], done=[0, 1]), kv=KV([['问候', '05 01 00'], ['请求', '05 01 00 01 + 地址 + 端口(CONNECT)'], ['回复', '05 00 …(成功 + BND 地址)'], ['握手', '2 个往返,13 + 12 字节']], ['请求'])),
    step("域名由谁解析?用 requests + PySocks 访问 example.com,经过本机 SOCKS5 服务器。socks5://:本机先做 DNS 解析,代理收到的请求 CMD = 1(CONNECT),ATYP = 1(IPv4),地址 104.20.23.154,端口 80,代理连目标用了 160 ms,客户端最终拿到 200 和 577 字节。socks5h://:代理收到的 ATYP = 3(域名),地址 example.com,端口 80,代理连目标 163 ms,客户端同样拿到 200 和 577 字节。区别:socks5 由客户端解析,代理只看到 IP;socks5h 把域名原样交给代理,由代理去解析——本机不发 DNS 查询。这是隐私(本地 DNS 查询不泄露要访问的域名)和绕开本地 DNS 污染的关键区别,写代理配置时 h 这个字母很容易漏。", t=tl(S(2)), mark=lidx(S(2), 'socks5://', 'socks5h://'), done=lidx(S(2), 'socks5:本机先做 DNS 解析'), kv=KV([['socks5://', '本机解析:ATYP=1,地址 104.20.23.154'], ['socks5h://', '代理解析:ATYP=3,地址 example.com'], ['区别', '本机是否发出 DNS 查询']], ['区别'])),
    step("用户名密码认证(RFC 1929)与错误答复。服务器要求认证时,选定方法 02(用户名/密码):正确的用户名密码 → 认证答复 01 00(成功);错误的密码 → 01 01(失败);如果客户端只提供“无需认证”→ 服务器答复 05 ff,没有可接受的认证方法。用户名和密码在 RFC 1929 里是明文传输的,只用来控制谁能用代理。错误状态码:连一个没有监听的端口 → 回复 05 05 …,状态码 5 = 连接被拒绝;域名无法解析 → 状态码 4(这个服务器把它报成“主机不可达”);不支持的命令(BIND = 2)→ 状态码 7;不支持的地址类型(0x09)→ 状态码 8。回复里的 BND 地址在失败时全是零。", t=tl(S(3)), mark=lidx(S(3), '正确的用户名密码', '错误的密码', '只提供'), done=lidx(S(3), '连接一个没有监听的端口', '域名无法解析', '不支持的命令', '不支持的地址类型'), kv=KV([['认证', '正确 01 00;错误 01 01;无可接受方法 05 ff'], ['状态码 5', '连接被拒绝'], ['状态码 4', '主机不可达(域名无法解析)'], ['状态码 7 / 8', '不支持的命令 / 地址类型']], ['状态码 5'])),
    step("UDP ASSOCIATE:SOCKS5 也能转发 UDP。客户端先用 TCP 控制连接发命令 3(UDP ASSOCIATE),服务器回复 05 00 00 01 7f 00 00 01 ca f2:状态 0,UDP 中继端口 51954。之后每个 UDP 数据报前面加 10 字节的 SOCKS5 UDP 头:00 00(RSV)| 00(FRAG,0 = 不分片)| 01(IPv4)| 01 01 01 01(1.1.1.1)| 00 35(端口 53),后面是 29 字节的 DNS 查询。通过中继发给 1.1.1.1 的 DNS 查询,收到中继回来的 71 字节数据报(前 10 字节是 SOCKS5 UDP 头,来源 1.1.1.1:53),里面的 DNS 响应是 [172.66.147.243, 104.20.23.154],用时 88 ms。UDP 中继的生命周期绑定在 TCP 控制连接上:关掉控制连接,服务器就停止中继。", t=tl(S(4)), mark=lidx(S(4), 'UDP ASSOCIATE 回复', '收到 UDP 中继回来的数据报'), done=lidx(S(4), 'UDP 数据报头', 'UDP 中继的生命周期'), b=bars([['SOCKS5 UDP 头', 10, '10 字节'], ['DNS 查询', 29, '29 字节'], ['回来的数据报', 71, '71 字节']], 71, mark=[0], done=[1, 2]), kv=KV([['UDP ASSOCIATE', '命令 3 + TCP 控制连接'], ['UDP 头', '00 00 | FRAG | ATYP | 地址 | 端口(10 字节)'], ['DNS 往返', '88 ms'], ['生命周期', '绑定 TCP 控制连接']], ['UDP 头'])),
]
A = mkartw('w101', 101, '网络协议,SOCKS5,代理,UDP ASSOCIATE,DNS,socks5h,真实验证,动画演示',
    '手工收发 SOCKS5 的每个字节:问候 05 01 00,CONNECT 请求 05 01 00 01 + 地址 + 端口,握手共 2 个往返 25 字节;socks5 与 socks5h 的区别是代理收到 ATYP=1 的 IP 还是 ATYP=3 的域名;用户名密码认证与错误码 5 / 4 / 7 / 8;UDP ASSOCIATE 加 10 字节 UDP 头转发真实 DNS 查询(88 ms)。',
    'SOCKS5 是最简单、最通用的代理协议:几个字节的握手,之后就是一根透明的管子。这篇自己实现了一个 SOCKS5 服务器,手工发每个字节,看 socks5 与 socks5h 到底谁解析域名,认证和各种错误怎么表示,以及它怎么转发 UDP。',
    [('25 字节', 'SOCKS5 CONNECT 握手的上下行总字节(13 + 12),共 2 个往返'), ('ATYP 1 vs 3', 'socks5 与 socks5h 下代理收到的地址类型(IPv4 / 域名)'), ('10 字节', 'SOCKS5 的 UDP 数据报头长度(IPv4)')],
    [('握手', '<p>问候选认证方法,请求带命令、地址类型、地址、端口,回复带状态码和绑定地址。</p>'),
     ('谁解析域名', '<p>socks5 本机解析,socks5h 代理解析;写配置时差一个字母,隐私就不同。</p>'),
     ('认证与错误', '<p>用户名密码明文(RFC 1929);状态码 5 拒绝、4 主机不可达、7 命令不支持、8 地址类型不支持。</p>'),
     ('UDP', '<p>UDP ASSOCIATE 之后,每个 UDP 数据报加 10 字节头;中继随 TCP 控制连接结束。</p>')],
    steps,
    [ENV_W + '。SOCKS5 服务器是我写的最小实现(线程 + 套接字,只支持 CONNECT 与 UDP ASSOCIATE,不支持 BIND 与 IPv6 的 UDP);客户端第一节是手工拼字节,第二节用 requests + PySocks;UDP 中继测试的 DNS 目标是 1.1.1.1;没有使用任何现成的代理软件',
     '没有验证:BIND 命令(反向连接);GSSAPI 认证;UDP 分片(FRAG 非零);IPv6 目标;大量并发连接下的性能;与 HTTP 代理(w83)在 HTTPS 上的行为对比;Tor 之类的 SOCKS5 实际部署;本机 DNS 被污染时 socks5 与 socks5h 的实际差别(没有去验证污染)'],
    'SOCKS5')
